<style>
    .input-group{margin-bottom:15px}.input-group label{display:block;font-weight:700;margin-bottom:5px;color:#333}.input-group input[type=text],.input-group input[type=number],.input-group input[type=file],.input-group textarea,.input-group select{width:100%;padding:10px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box}.form-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,1fr);gap:20px}.section-title{border-bottom:2px solid #17a2b8;padding-bottom:5px;margin-bottom:15px;font-size:18px;font-weight:700}.feature-row{display:grid;grid-template-columns:minmax(180px,1fr) 100px auto auto;gap:10px;margin-bottom:10px;align-items:center}.feature-row input[type=text],.feature-row input[type=number]{width:100%;padding:8px;box-sizing:border-box}.check-row{display:flex;flex-wrap:wrap;gap:18px}.remove-btn{background:#dc3545;color:#fff;border:0;padding:8px;border-radius:3px;cursor:pointer}.add-btn{padding:8px 12px;background:#28a745;color:#fff;border:0;border-radius:3px;cursor:pointer}.submit-btn{padding:12px 20px;background:#17a2b8;color:#fff;border:0;cursor:pointer;margin-top:20px;width:100%;font-size:16px;border-radius:4px}@media(max-width:900px){.form-grid{grid-template-columns:1fr}.feature-row{grid-template-columns:1fr 90px}.feature-row label,.feature-row button{justify-self:start}}
</style>
